/* ===================================================
   Startup Failure Analysis — Global Styles (Light Theme)
   =================================================== */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500&display=swap');

/* ── Root tokens ─────────────────────────────────── */
:root {
    --bg-primary: #f4f6f8;
    --bg-secondary: #ffffff;
    --bg-card: #ffffff;
    --bg-card-hover: #f8fafc;
    --border: rgba(30,59,58,0.1);
    --border-hover: rgba(30,59,58,0.3);
    
    --accent-dark: #112222;
    --accent-teal: #1e3b3a;
    --accent-light: #3f6866;
    
    --text-primary: #0f172a;
    --text-secondary: #334155;
    --text-muted: #64748b;
    
    --success: #10b981;
    --danger: #ef4444;
    --warning: #f59e0b;
    --info: #3b82f6;
    --purple: #8b5cf6;
    
    --font-main: 'Inter', sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
    
    --radius: 12px;
    --radius-sm: 8px;
    --shadow: 0 4px 12px rgba(0,0,0,0.03);
    --shadow-hover: 0 10px 25px rgba(0,0,0,0.08);
}

/* ── Base ────────────────────────────────────────── */
html, body, [data-testid="stAppViewContainer"] {
    font-family: var(--font-main) !important;
    background: var(--bg-primary) !important;
    color: var(--text-primary) !important;
}

[data-testid="stHeader"] {
    background: transparent !important;
}

/* ── Sidebar ─────────────────────────────────────── */
[data-testid="stSidebar"] {
    background: var(--bg-secondary) !important;
    border-right: 1px solid var(--border) !important;
}

[data-testid="stSidebar"] .stSelectbox label,
[data-testid="stSidebar"] .stSlider label,
[data-testid="stSidebar"] .stMultiSelect label {
    color: var(--text-secondary) !important;
    font-size: 0.8rem !important;
    font-weight: 500 !important;
    text-transform: uppercase !important;
}

/* Sidebar Logo / Brand block */
.ag-sidebar-brand {
    background: var(--accent-teal);
    color: white;
    padding: 1.25rem;
    border-radius: var(--radius-sm);
    margin-bottom: 1.5rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-weight: 600;
    box-shadow: var(--shadow);
}
.ag-sidebar-brand-icon {
    font-size: 1.25rem;
}

/* Sidebar Quote */
.ag-sidebar-quote {
    margin-top: 2rem;
    padding: 1.5rem 1rem;
    border-top: 1px solid var(--border);
    color: var(--text-secondary);
    font-size: 0.85rem;
    font-style: italic;
    line-height: 1.5;
}
.ag-sidebar-quote::before {
    content: '“';
    font-size: 3rem;
    color: var(--border-hover);
    line-height: 0.1;
    display: block;
    margin-bottom: 0.5rem;
}

/* ── Top Navigation Bar ──────────────────────────── */
.ag-top-nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 1.5rem;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border);
    border-radius: var(--radius);
    margin-bottom: 1.5rem;
    box-shadow: var(--shadow);
}
.ag-search-bar {
    background: var(--bg-primary);
    border: 1px solid var(--border);
    padding: 0.5rem 1rem;
    border-radius: 100px;
    font-size: 0.85rem;
    color: var(--text-secondary);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    width: 300px;
}
.ag-nav-tools {
    display: flex;
    align-items: center;
    gap: 1rem;
    font-size: 0.85rem;
    color: var(--text-secondary);
}

/* ── Hero Section ────────────────────────────────── */
.ag-hero {
    background-image: url("data:image/jpeg;base64,"); /* Will be loaded if placed in static, but Streamlit doesn't easily serve static CSS images. Instead we'll inject via inline style in the component. */
    background-size: cover;
    background-position: center;
    border-radius: var(--radius);
    padding: 3.5rem 3rem;
    margin-bottom: 1.5rem;
    position: relative;
    overflow: hidden;
    box-shadow: var(--shadow);
    color: var(--text-primary);
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.ag-hero::before {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(90deg, rgba(255,255,255,0.95) 0%, rgba(255,255,255,0.85) 40%, rgba(255,255,255,0) 100%);
    z-index: 1;
}

.ag-hero > * {
    position: relative;
    z-index: 2;
}

.ag-hero-content {
    max-width: 600px;
}

.ag-hero-pretitle {
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 1rem;
}

.ag-hero-title {
    font-size: 3.5rem;
    font-weight: 900;
    line-height: 1.1;
    margin-bottom: 0.5rem;
    color: var(--text-primary);
}
.ag-hero-title span {
    color: var(--accent-light);
}

.ag-hero-subtitle {
    font-size: 1.5rem;
    font-weight: 400;
    color: var(--text-secondary);
    margin-bottom: 1.25rem;
}

.ag-hero-desc {
    font-size: 0.95rem;
    color: var(--text-secondary);
    line-height: 1.6;
    margin-bottom: 2rem;
    border-left: 2px solid var(--accent-light);
    padding-left: 1rem;
}

.ag-hero-buttons {
    display: flex;
    gap: 1rem;
}

.ag-btn-primary {
    background: var(--accent-teal);
    color: white;
    padding: 0.75rem 1.5rem;
    border-radius: var(--radius-sm);
    font-weight: 600;
    font-size: 0.9rem;
    text-decoration: none;
    box-shadow: 0 4px 10px rgba(30,59,58,0.2);
}
.ag-btn-secondary {
    background: transparent;
    color: var(--accent-teal);
    border: 1px solid var(--accent-teal);
    padding: 0.75rem 1.5rem;
    border-radius: var(--radius-sm);
    font-weight: 600;
    font-size: 0.9rem;
    text-decoration: none;
}

/* ── Metric Cards ────────────────────────────────── */
.ag-metric-row {
    display: flex;
    gap: 1rem;
    margin-bottom: 1.5rem;
    flex-wrap: wrap;
}

.ag-metric-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 1.25rem 1rem;
    flex: 1;
    min-width: 120px;
    box-shadow: var(--shadow);
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

.ag-metric-icon {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.1rem;
    margin-bottom: 0.75rem;
}

.ag-metric-value {
    font-size: 1.5rem;
    font-weight: 800;
    color: var(--text-primary);
    line-height: 1;
    margin-bottom: 0.25rem;
}

.ag-metric-label {
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--text-muted);
}
.ag-metric-sub {
    font-size: 0.7rem;
    font-weight: 700;
    margin-top: 0.2rem;
}

/* ── Standard Cards ──────────────────────────────── */
.ag-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 1.5rem;
    box-shadow: var(--shadow);
    margin-bottom: 1.5rem;
}
.ag-card-header {
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 0.25rem;
    color: var(--text-primary);
}
.ag-card-sub {
    font-size: 0.8rem;
    color: var(--text-muted);
    margin-bottom: 1rem;
}

/* ── Key Takeaways List ──────────────────────────── */
.ag-takeaway-item {
    display: flex;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    align-items: flex-start;
}
.ag-takeaway-icon {
    font-size: 1.25rem;
    margin-top: 0.1rem;
}
.ag-takeaway-text {
    font-size: 0.85rem;
    color: var(--text-secondary);
    line-height: 1.5;
}

/* ── Footer Banner ───────────────────────────────── */
.ag-footer-banner {
    border-radius: var(--radius);
    padding: 2.5rem 3rem;
    margin-top: 2rem;
    margin-bottom: 2rem;
    position: relative;
    overflow: hidden;
    box-shadow: var(--shadow);
    color: white;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.ag-footer-banner::before {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(90deg, rgba(17,34,34,0.9) 0%, rgba(17,34,34,0.6) 100%);
    z-index: 1;
}

.ag-footer-content {
    position: relative;
    z-index: 2;
}

.ag-footer-pre {
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: rgba(255,255,255,0.7);
    margin-bottom: 0.5rem;
}
.ag-footer-title {
    font-size: 1.5rem;
    font-weight: 500;
}
.ag-footer-link {
    position: relative;
    z-index: 2;
    font-size: 0.85rem;
    color: rgba(255,255,255,0.8);
    text-decoration: none;
}

/* ── Hide Streamlit defaults ─────────────────────── */
footer { visibility: hidden; }
header { visibility: hidden; }

.ag-footer-banner {
    background-image: url("data:image/jpeg;base64,");
    background-size: cover;
    background-position: center;
}
